import base64, ctypes as c, io, os, shutil, subprocess, time
from pathlib import Path
from pywinauto import Desktop

PROFILE=Path(os.environ["USERPROFILE"])
targets=("\ubc14\ud0d5 \ud654\uba74","\ubb38\uc11c","\ub2e4\uc6b4\ub85c\ub4dc","\uc0ac\uc9c4","\uc74c\uc545","\ub3d9\uc601\uc0c1")

def until(fn,why,timeout=30):
    end=time.monotonic()+timeout
    while time.monotonic()<end:
        try:
            v=fn()
            if v:return v
        except Exception:pass
        time.sleep(.3)
    raise AssertionError(why)

def find_auto(root,auto_id):
    for x in root.descendants():
        try:
            if x.element_info.automation_id==auto_id:return x
        except Exception:pass
    return None

def rows_for(root):
    found={}
    for item in root.descendants():
        try:
            if item.element_info.control_type!="ListItem":continue
            name=item.element_info.name or item.window_text()
            for t in targets:
                if t in name:found.setdefault(t,(item,name))
        except Exception:pass
    return found

def image_counts(rows):
    known=generic=0
    for t in targets:
        item,_=rows[t]
        for x in item.descendants():
            try:
                if x.element_info.control_type!="Image":continue
                if x.element_info.name=="Windows Known Folder artwork":known+=1
                if x.element_info.name=="Windows Shell folder icon":generic+=1
            except Exception:pass
    return known,generic

def capture(exe,root,label):
    owned=root/"logs"/("known-folder-"+label.lower())
    if owned.exists():shutil.rmtree(owned)
    (owned/"localappdata"/"flyExplorer").mkdir(parents=True)
    (owned/"localappdata"/"flyExplorer"/"ui-preferences-v1.txt").write_text(
      "schema=2\r\nlanguage=ko-KR\r\ntheme=dark\r\nview=large-icons\r\n",encoding="ascii",newline="")
    env=os.environ.copy();env["LOCALAPPDATA"]=str(owned/"localappdata")
    p=subprocess.Popen([str(exe),str(PROFILE)],cwd=exe.parent,env=env)
    w=None
    try:
        w=until(lambda:next((x for x in Desktop(backend="uia").windows(process=p.pid)
                            if "flyExplorer" in x.window_text()),None),label+" window")
        try:w.move_window(x=40,y=40,width=972,height=720,repaint=True)
        except Exception:pass
        left=until(lambda:find_auto(w,"LeftFiles"),label+" LeftFiles")
        rows=until(lambda:(lambda x:x if len(x)>=6 else None)(rows_for(left)),label+" known rows",30)
        until(lambda:(lambda c:c if sum(c)>=6 else None)(image_counts(rows)),label+" images",30)
        mode="none"
        try:
            rows["\uc74c\uc545"][0].iface_scroll_item.ScrollIntoView();mode="uia-scroll-item"
        except Exception:pass
        time.sleep(1.4)
        known,generic=image_counts(rows)
        print(label+"_KNOWN_COUNT",known,label+"_GENERIC_COUNT",generic,label+"_SCROLL",mode,flush=True)
        for t in targets:
            r=rows[t][0].rectangle()
            print(label+"_ROW",repr(t),r.left,r.top,r.width(),r.height(),flush=True)
        im=w.capture_as_image().convert("RGB")
        buf=io.BytesIO();im.save(buf,format="JPEG",quality=86,optimize=True)
        print(label+"_SCREENSHOT_BEGIN",flush=True)
        print(base64.b64encode(buf.getvalue()).decode("ascii"),flush=True)
        print(label+"_SCREENSHOT_END",flush=True)
    finally:
        if p.poll() is None:
            if w:c.windll.user32.PostMessageW(w.handle,0x10,0,0)
            try:p.wait(timeout=10)
            except subprocess.TimeoutExpired:p.terminate();p.wait(timeout=8)
    print(label+"_EXIT",p.returncode,flush=True)

capture(Path(r"C:\dev\flyExplorer-before-known-folder\out\winui\Release\flyExplorer.exe"),
        Path(r"C:\dev\flyExplorer-before-known-folder"),"BEFORE")
capture(Path(r"C:\dev\flyExplorer\out\winui\Release\flyExplorer.exe"),
        Path(r"C:\dev\flyExplorer"),"AFTER")

